    intermittent = "Intermittent: " + Replace($feature.intermittent,"_"," ") + TextFormatting.NewLine
}
var seasonal = ""
if(IsEmpty($feature.seasonal) == false){
    seasonal = "Seasonal: " + Replace($feature.seasonal,"_"," ") + TextFormatting.NewLine
}
var tunnel = ""
