    layer = "Layer: " + Replace($feature.layer,"_"," ") + TextFormatting.NewLine
}
var source_date = ""
if(IsEmpty($feature.source_date) == false){
    source_date = "Source Date: " + Replace($feature.source_date,"_"," ") + TextFormatting.NewLine
